//! Thin FFI wrapper around the vendored fadec x86-64 encoder (`vendor/fadec`).
//!
//! Mnemonic constants (`FE_ADD64rr`, `FE_JMP`, `FE_MOV64rm`, ...) are generated by `build.rs`
//! from `fadec-encode-public.inc`. Register / memory-operand helpers mirror `fadec-enc.h`.
#![allow(non_upper_case_globals, dead_code)]

include!(concat!(env!("OUT_DIR"), "/fadec_mnemonics.rs"));

pub type FeOp = i64;

// Registers (FeReg in fadec-enc.h)
pub const FE_NOREG: FeOp = 0;
pub const FE_AX: FeOp = 0x100;
pub const FE_CX: FeOp = 0x101;
pub const FE_DX: FeOp = 0x102;
pub const FE_BX: FeOp = 0x103;
pub const FE_SP: FeOp = 0x104;
pub const FE_BP: FeOp = 0x105;
pub const FE_SI: FeOp = 0x106;
pub const FE_DI: FeOp = 0x107;
pub const FE_R8: FeOp = 0x108;
pub const FE_R9: FeOp = 0x109;
pub const FE_R10: FeOp = 0x10a;
pub const FE_R11: FeOp = 0x10b;
pub const FE_R12: FeOp = 0x10c;
pub const FE_R13: FeOp = 0x10d;
pub const FE_R14: FeOp = 0x10e;
pub const FE_R15: FeOp = 0x10f;
pub const FE_IP: FeOp = 0x120;
pub const FE_AH: FeOp = 0x204;
pub const FE_CH: FeOp = 0x205;
pub const FE_DH: FeOp = 0x206;
pub const FE_BH: FeOp = 0x207;
pub const FE_XMM0: FeOp = 0x600;

/// General purpose register number `n` (0 = rax/eax/ax/al ... 15 = r15). Size is selected by
/// the mnemonic (e.g. `FE_MOV8rr` vs `FE_MOV64rr`); `spl/bpl/sil/dil` are `gp(4..=7)` with an
/// 8-bit mnemonic, the legacy high-byte registers are `FE_AH..FE_BH`.
pub const fn gp(n: u8) -> FeOp {
    0x100 + n as FeOp
}

/// `FE_MEM(base, scale, index, offset)`. With `base == FE_IP` the offset is relative to the
/// *start* of the instruction being encoded (fadec subtracts the instruction length).
pub const fn mem(base: FeOp, scale: u8, index: FeOp, off: i32) -> FeOp {
    i64::MIN
        | ((base & 0xfff) << 32)
        | ((index & 0xfff) << 44)
        | (((scale as i64) & 0xf) << 56)
        | ((off as i64) & 0xffff_ffff)
}

/// Force the rel32 form of a jump/jcc/call (or-ed into the mnemonic).
pub const FE_JMPL: u64 = 0x1_0000_0000;
/// 32-bit address-size override (or-ed into the mnemonic).
pub const FE_ADDR32: u64 = 0x1000_0000;

extern "C" {
    fn fe_enc64_impl(buf: *mut *mut u8, mnem: u64, op0: FeOp, op1: FeOp, op2: FeOp, op3: FeOp) -> i32;
}

/// Encode one instruction. `ops` holds up to four operands (immediates as plain values,
/// registers as `FE_*`/`gp()`, memory operands via `mem()`).
///
/// Branch targets: fadec expects the *absolute address in the output buffer* of the target.
/// Use [`encode_branch`] for jumps/calls instead of passing raw targets here.
pub fn encode(mnem: u64, ops: &[FeOp]) -> Result<Vec<u8>, ()> {
    assert!(ops.len() <= 4);
    let mut o = [0 as FeOp; 4];
    o[..ops.len()].copy_from_slice(ops);
    let mut buf = [0u8; 16];
    let mut ptr = buf.as_mut_ptr();
    let rc = unsafe { fe_enc64_impl(&mut ptr, mnem, o[0], o[1], o[2], o[3]) };
    if rc != 0 {
        return Err(());
    }
    let len = ptr as usize - buf.as_ptr() as usize;
    Ok(buf[..len].to_vec())
}

/// Encode a relative branch (`FE_JMP`, `FE_Jcc` like `FE_JZ`, `FE_CALL`) located at section
/// offset `at`, jumping to section offset `target`. Or `FE_JMPL` into `mnem` to force rel32.
pub fn encode_branch(mnem: u64, at: u64, target: u64) -> Result<Vec<u8>, ()> {
    let mut buf = [0u8; 16];
    let base = buf.as_mut_ptr();
    let tgt = (base as i64).wrapping_add(target as i64 - at as i64);
    let mut ptr = base;
    let rc = unsafe { fe_enc64_impl(&mut ptr, mnem, tgt, 0, 0, 0) };
    if rc != 0 {
        return Err(());
    }
    let len = ptr as usize - base as usize;
    Ok(buf[..len].to_vec())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn smoke() {
        assert_eq!(encode(FE_ADD64rr, &[FE_AX, FE_CX]).unwrap(), vec![0x48, 0x01, 0xc8]);
        assert_eq!(encode(FE_RET, &[]).unwrap(), vec![0xc3]);
        assert_eq!(encode_branch(FE_JMP, 0, 0).unwrap(), vec![0xeb, 0xfe]);
        assert_eq!(encode_branch(FE_JMP | FE_JMPL, 0, 0).unwrap(), vec![0xe9, 0xfb, 0xff, 0xff, 0xff]);
    }
}
